"""Molecular Studio: 2D depiction and 3D conformer generation for inspection in the browser.

**The scientific distinction this module exists to protect.**

Everything produced here is *computed*, not measured:

* A 2D depiction is a drawing. Coordinates are generated for legibility and carry no physical meaning.
* A 3D conformer is **generated by a distance-geometry algorithm (ETKDG) and optimised with a force
  field (MMFF94/UFF)**. It is a plausible low-energy geometry, **not an experimentally determined
  structure**. It is not a crystal structure, not an NMR structure, and not a bound/bioactive
  conformation.
* Nothing here performs docking. There is no protein, no binding site, no pose and no affinity. A
  molecular viewer is not a docking program.

Every payload therefore carries an explicit `structure_origin` and a `disclaimer`, so a screenshot of
the viewer cannot be mistaken for experimental structural data.

`structure_origin` values:
    computed_conformer   - generated here by RDKit from a SMILES string
    computed_depiction   - 2D coordinates generated here for drawing
    imported             - a structure supplied by a provider or researcher, used as given
    experimental         - reserved; MOLECULAB does not currently ingest experimental structures
"""
from __future__ import annotations

import logging

from rdkit import Chem
from rdkit.Chem import AllChem, Draw
from rdkit.Chem.Draw import rdMolDraw2D

from app.molecules import MAX_ATOMS, descriptors, parse_smiles, resolve_structure

log = logging.getLogger("moleculab")

CONFORMER_DISCLAIMER = (
    "Computed 3D conformer (RDKit ETKDG + force-field optimisation). This is a plausible low-energy "
    "geometry, NOT an experimentally determined structure and NOT a bound or bioactive conformation. "
    "No docking was performed: there is no protein, binding site, pose or affinity in this view."
)
DEPICTION_DISCLAIMER = (
    "Computed 2D depiction. Coordinates are generated for legibility and carry no physical meaning."
)

#: 3D embedding is the one genuinely expensive call here; keep it bounded for interactive use.
MAX_3D_ATOMS = 150
EMBED_SEED = 0xC0FFEE  # fixed seed: the same SMILES yields the same conformer, so a demo is repeatable


def depict_2d(smiles: str, width: int = 420, height: int = 320,
              highlight_smarts: str | None = None) -> dict:
    """Render a 2D SVG depiction. Returns {ok, svg, structure_origin, disclaimer} or {ok: False, error}."""
    mol, error = parse_smiles(smiles)
    if mol is None:
        return {"ok": False, "error": error, "structure_origin": None}
    try:
        drawing = Chem.Mol(mol)
        rdMolDraw2D.PrepareMolForDrawing(drawing)  # adds 2D coords, sanitises wedging
        drawer = rdMolDraw2D.MolDraw2DSVG(width, height)
        options = drawer.drawOptions()
        # Dark-theme palette: light carbons so bonds are legible on the dark shell, with conventional
        # heteroatom colours retained (O red, N blue, S yellow) so the depiction stays readable as
        # chemistry rather than decoration.
        options.setBackgroundColour((0.043, 0.055, 0.071, 1.0))
        options.updateAtomPalette({
            -1: (0.88, 0.91, 0.96),   # default / carbon
            1: (0.80, 0.84, 0.90),    # H
            6: (0.88, 0.91, 0.96),    # C
            7: (0.45, 0.65, 1.00),    # N
            8: (1.00, 0.42, 0.42),    # O
            9: (0.45, 0.90, 0.60),    # F
            15: (1.00, 0.68, 0.35),   # P
            16: (1.00, 0.85, 0.35),   # S
            17: (0.45, 0.90, 0.60),   # Cl
            35: (0.85, 0.60, 0.40),   # Br
            53: (0.75, 0.55, 0.95),   # I
        })
        options.setSymbolColour((0.90, 0.92, 0.96))
        options.setAnnotationColour((0.60, 0.78, 1.00))
        options.bondLineWidth = 2
        options.addStereoAnnotation = True  # stereocentres are labelled, never silently dropped
        highlights = []
        if highlight_smarts:
            pattern = Chem.MolFromSmarts(highlight_smarts)
            if pattern is not None:
                highlights = [i for match in drawing.GetSubstructMatches(pattern) for i in match]
        drawer.DrawMolecule(drawing, highlightAtoms=highlights or None)
        drawer.FinishDrawing()
        return {"ok": True, "svg": drawer.GetDrawingText(),
                "structure_origin": "computed_depiction", "disclaimer": DEPICTION_DISCLAIMER}
    except Exception as exc:  # a drawing failure must never take down the request
        log.warning("2D depiction failed: %s", exc)
        return {"ok": False, "error": f"depiction failed: {type(exc).__name__}",
                "structure_origin": None}


def conformer_3d(smiles: str, optimise: bool = True) -> dict:
    """Generate one 3D conformer and return it as a MOL block.

    Stereochemistry from the input SMILES is preserved: hydrogens are added before embedding and the
    chiral tags travel with the molecule. The result is labelled a computed conformer.
    """
    mol, error = parse_smiles(smiles)
    if mol is None:
        return {"ok": False, "error": error, "structure_origin": None}
    if mol.GetNumAtoms() > MAX_3D_ATOMS:
        return {"ok": False, "structure_origin": None,
                "error": f"structure has {mol.GetNumAtoms()} heavy atoms; 3D generation is limited to "
                         f"{MAX_3D_ATOMS} for interactive use"}
    try:
        molh = Chem.AddHs(mol)  # explicit H before embedding gives sane geometry
        params = AllChem.ETKDGv3()
        params.randomSeed = EMBED_SEED
        params.useSmallRingTorsions = True
        if AllChem.EmbedMolecule(molh, params) != 0:
            # Retry with random coordinates; some cage-like structures fail the standard embedding.
            params.useRandomCoords = True
            if AllChem.EmbedMolecule(molh, params) != 0:
                return {"ok": False, "structure_origin": None,
                        "error": "3D embedding failed: RDKit could not generate a conformer for this "
                                 "structure"}
        force_field, converged = None, None
        if optimise:
            try:
                if AllChem.MMFFHasAllMoleculeParams(molh):
                    converged = AllChem.MMFFOptimizeMolecule(molh, maxIters=400)
                    force_field = "MMFF94"
                else:
                    converged = AllChem.UFFOptimizeMolecule(molh, maxIters=400)
                    force_field = "UFF"
            except Exception as exc:
                log.warning("3D optimisation failed, returning unoptimised conformer: %s", exc)
                force_field = None
        return {
            "ok": True,
            "molblock": Chem.MolToMolBlock(molh),
            "format": "mol",
            "atom_count": molh.GetNumAtoms(),
            "heavy_atom_count": mol.GetNumHeavyAtoms(),
            "structure_origin": "computed_conformer",
            "method": {
                "embedding": "RDKit ETKDGv3 (distance geometry)",
                "force_field": force_field,
                # 0 means the optimiser converged; 1 means it hit the iteration limit.
                "optimisation_converged": (converged == 0) if converged is not None else None,
                "random_seed": EMBED_SEED,
                "deterministic": True,
            },
            "disclaimer": CONFORMER_DISCLAIMER,
        }
    except Exception as exc:
        log.warning("3D conformer generation failed: %s", exc)
        return {"ok": False, "error": f"3D generation failed: {type(exc).__name__}",
                "structure_origin": None}


def atom_bond_inventory(smiles: str) -> dict:
    """Per-element atom counts and bond-order counts, for the inspection panel."""
    mol, error = parse_smiles(smiles)
    if mol is None:
        return {"ok": False, "error": error}
    elements: dict[str, int] = {}
    for atom in mol.GetAtoms():
        elements[atom.GetSymbol()] = elements.get(atom.GetSymbol(), 0) + 1
    bonds: dict[str, int] = {}
    for bond in mol.GetBonds():
        name = str(bond.GetBondType()).title()
        bonds[name] = bonds.get(name, 0) + 1
    return {"ok": True, "elements": dict(sorted(elements.items(), key=lambda kv: -kv[1])),
            "bonds": bonds, "heavy_atoms": mol.GetNumHeavyAtoms(),
            "rings": mol.GetRingInfo().NumRings()}


def studio_payload(smiles: str, *, name: str | None = None, identifiers: dict | None = None,
                   provenance: dict | None = None, want_3d: bool = True) -> dict:
    """Everything the Molecular Studio needs for one compound.

    Carries the submitted structure, the standardized structure, the transformation log, descriptors,
    a 2D depiction and (optionally) a 3D conformer — each labelled with what kind of thing it is.
    """
    record = resolve_structure(smiles)
    if not record.valid:
        return {"ok": False, "error": record.error, "name": name,
                "identifiers": identifiers or {}, "input_smiles": smiles}

    payload = {
        "ok": True,
        "name": name,
        "identifiers": identifiers or {},
        "provenance": provenance or {},
        # Submitted vs standardized are never collapsed into one field.
        "input_smiles": record.input_value,
        "original_smiles": record.original_smiles,
        "standardized_smiles": record.standardized_smiles,
        "standardization_changed": record.standardization_changed,
        "transformations": record.transformations,
        "inchi": record.inchi,
        "inchikey": record.inchikey,
        "skeleton_key": record.skeleton_key,
        "scaffold_smiles": record.scaffold_smiles,
        "descriptors": record.descriptors,
        "stereo": {
            "stereo_centers": record.stereo_centers,
            "unspecified_stereo_centers": record.unspecified_stereo_centers,
            "has_defined_stereo": record.has_defined_stereo,
        },
        "chemistry_version": record.chemistry_version,
        "atom_bond_inventory": atom_bond_inventory(record.standardized_smiles),
        "depiction_2d": depict_2d(record.standardized_smiles),
        # The structure MOLECULAB holds is a SMILES string from a database, not a measured geometry.
        "source_structure_origin": "imported",
        "source_structure_note": (
            "MOLECULAB stores this compound as a SMILES string imported from its source database. "
            "No experimentally determined 3D structure is held for it."),
    }
    payload["conformer_3d"] = conformer_3d(record.standardized_smiles) if want_3d else {
        "ok": False, "error": "not requested", "structure_origin": None}
    return payload


def compare(smiles_a: str, smiles_b: str) -> dict:
    """Side-by-side comparison of two structures: descriptors and structural similarity."""
    from app.molecules import tanimoto

    mol_a, err_a = parse_smiles(smiles_a)
    mol_b, err_b = parse_smiles(smiles_b)
    if mol_a is None or mol_b is None:
        return {"ok": False, "error": err_a or err_b}
    desc_a, desc_b = descriptors(mol_a), descriptors(mol_b)
    numeric = [k for k, v in desc_a.items() if isinstance(v, (int, float))]
    return {
        "ok": True,
        "tanimoto": tanimoto(mol_a, mol_b),
        "similarity_note": ("Morgan/Tanimoto structural similarity. This is a comparison of chemical "
                            "structure only and is not evidence of shared biological activity."),
        "descriptors": {key: {"a": desc_a.get(key), "b": desc_b.get(key),
                              "delta": round(desc_b[key] - desc_a[key], 4)} for key in numeric},
        "formula": {"a": desc_a.get("molecular_formula"), "b": desc_b.get("molecular_formula")},
    }
